// Контракт із бекендом: platform_background приходить назвою відтінку.
// Єдине місце, де назви відтінків приймаються як дані; невідоме значення
// (hex, опечатка, новий колір на бекенді) дає нейтральний тон, а не
// тихо прозорий чип.
const BACKEND_HUE_TONES = {
    gray: 'neutral',
    red: 'danger',
    green: 'success',
    orange: 'warning',
    blue: 'info',
    violet: 'accent',
    yellow: 'warning',
};
export const toneFromBackendHue = (raw, fallback = 'neutral') => (typeof raw === 'string' && Object.prototype.hasOwnProperty.call(BACKEND_HUE_TONES, raw)
    ? BACKEND_HUE_TONES[raw]
    : fallback);
